func TestExporterNoopExports(t *testing.T) {
	// Submit on a nil exporter must drop silently.
	var e *Exporter
	e.Submit(nil)
	e.Submit(&Span{Name: "x"})
	if e.Dropped() != 0 {
		t.Errorf("nil exporter Dropped() = %d", e.Dropped())
