// Package tracing provides W3C Trace Context-compatible distributed
// tracing with an OTLP/JSON HTTP exporter.
//
// The API is stdlib-only (crypto/rand, encoding/hex, encoding/json,
// net/http) and is designed so NEXUS_TRACING_ENDPOINT="" (the
// default) disables the entire subsystem: no background goroutines,
// no allocations beyond a nil-check on every StartSpan call.
//
// When enabled, the chat handler wraps each request phase (RAG, TOON,
// routing, upstream, streaming) in a Span tree. A background exporter
// buffers spans and POSTs them to the configured OTLP/JSON endpoint
// in batches so a stalled collector never blocks the request path.
//
// Inbound W3C `traceparent` headers are honoured so spans from an
// upstream caller attach to the same trace. Missing or malformed
// headers fall through to a fresh trace id, keeping the hot path
// unaffected when the harness does not propagate context.
//
// Reference: https://www.w3.org/TR/trace-context/ and
// https://opentelemetry.io/docs/specs/otlp/#json-protobuf-encoding.

display.text:
// Package tracing provides W3C Trace Context-compatible distributed
// tracing with an OTLP/JSON HTTP exporter.
//
// The API is stdlib-only (crypto/rand, encoding/hex, encoding/json,
// net/http) and is designed so NEXUS_TRACING_ENDPOINT="" (the
// default) disables the entire subsystem: no background goroutines,
// no allocations beyond a nil-check on every StartSpan call.
//
// When enabled, the chat handler wraps each request phase (RAG, TOON,
// routing, upstream, streaming) in a Span tree. A background exporter
// buffers spans and POSTs them to the configured OTLP/JSON endpoint
// in batches so a stalled collector never blocks the request path.
//
// Inbound W3C `traceparent` headers are honoured so spans from an
// upstream caller attach to the same trace. Missing or malformed
// headers fall through to a fresh trace id, keeping the hot path
// unaffected when the harness does not propagate context.
//
// Reference: https://www.w3.org/TR/trace-context/ and
// https://opentelemetry.io/docs/specs/otlp/#json-protobuf-encoding.
package tracing

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"sync"
	"sync/atomic"
	"time"
)

// traceIDLen / spanIDLen are the W3C Trace Context byte lengths (16 /
// 8 bytes -> 32 / 16 hex chars). Both IDs are rendered lowercase hex
// so the OTLP collector accepts them verbatim.
const (
	traceIDLen = 16
	spanIDLen  = 8
)

// Context carries the active trace and span id. It is threaded
// through the request lifecycle so child spans attach to the correct
// parent.
//
// A zero-value Context (TraceID == "") is the "no tracing in scope"
// sentinel; StartSpan on it produces a new root span instead of
// attaching to a non-existent parent.
type Context struct {
	TraceID string
	SpanID  string
}

// WithSpanID returns a new Context with SpanID replaced. Useful when
// a callee only needs the new span id without the full Context.
func (c Context) WithSpanID(spanID string) Context {
	return Context{TraceID: c.TraceID, SpanID: spanID}
}

// NewTraceID returns a fresh 32-hex-char trace id, sourced from
// crypto/rand. Falls back to a time-based id when the kernel RNG is
// unreadable (extremely rare on linux); the fallback is unique enough
// for log correlation but is not cryptographically unique.
func NewTraceID() string {
	var b [traceIDLen]byte
	if _, err := rand.Read(b[:]); err != nil {
		// Last-resort fallback so a broken /dev/urandom cannot crash
		// the binary on a hostile host. Uniqueness only matters for
		// trace correlation in this branch.
		return fmt.Sprintf("%032x", time.Now().UnixNano())
	}
	return hex.EncodeToString(b[:])
}

// NewSpanID returns a fresh 16-hex-char span id. Same fallback as
// NewTraceID.
func NewSpanID() string {
	var b [spanIDLen]byte
	if _, err := rand.Read(b[:]); err != nil {
		return fmt.Sprintf("%016x", time.Now().UnixNano())
	}
	return hex.EncodeToString(b[:])
}

// ParseTraceparent parses a W3C traceparent header value. Returns
// (traceID, spanID, ok). The accepted form is:
//
//	"00-<32 hex>-<16 hex>-<2 hex>"
//
// Rejected (returns ok=false): wrong version, malformed hex, wrong
// field lengths, or all-zero trace/span ids (which the W3C spec
// reserves as invalid). The trace-flags byte is accepted but the
// sampled bit is ignored — the OTLP exporter always sends every
// sampled span.
//
// The full W3C form is 55 characters; longer headers are rejected
// because the spec defines only the four fields above.
func ParseTraceparent(h string) (traceID, spanID string, ok bool) {
	const want = 55 // 2 + 1 + 32 + 1 + 16 + 1 + 2
	if len(h) != want {
		return "", "", false
	}
	if h[0:2] != "00" || h[2] != '-' || h[35] != '-' || h[52] != '-' {
		return "", "", false
	}
	traceID = h[3:35]
	spanID = h[36:52]
	if !isLowerHex(traceID) || !isLowerHex(spanID) {
		return "", "", false
	}
	// The W3C spec reserves all-zero trace and span ids as invalid
	// so a downstream service cannot confuse them with a real id.
	if isAllZero(traceID) || isAllZero(spanID) {
		return "", "", false
	}
	return traceID, spanID, true
}

// FormatTraceparent renders the W3C traceparent header for the given
// trace / span ids, using version 00 and the "sampled" flag set so
// downstream collectors do not skip the propagated span.
//
// Returns "" when traceID or spanID is empty so a partial context
// cannot produce an invalid header.
func FormatTraceparent(traceID, spanID string) string {
	if traceID == "" || spanID == "" {
		return ""
	}
	return "00-" + traceID + "-" + spanID + "-01"
}

// isLowerHex reports whether s is exactly len(s) lowercase hex
// characters. Used by ParseTraceparent to validate the W3C id fields.
func isLowerHex(s string) bool {
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(('0' <= c && c <= '9') || ('a' <= c && c <= 'f')) {
			return false
		}
	}
	return true
}

// isAllZero reports whether every byte of s is '0'. Used by
// ParseTraceparent to reject the W3C-reserved invalid ids.
func isAllZero(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] != '0' {
			return false
		}
	}
	return true
}

// Status enumerates the W3C / OTLP span status codes.
type Status int

const (
	// StatusUnset is the zero value; the exporter renders it as
	// STATUS_CODE_UNSET per the OTLP enum. A span that ends
	// without a status is considered "in progress" by collectors.
	StatusUnset Status = iota
	// StatusOK indicates a successful operation.
	StatusOK
	// StatusError indicates a failure; the StatusMessage carries
	// the human-readable detail.
	StatusError
)

// String returns the canonical OTLP enum spelling for the status.
func (s Status) String() string {
	switch s {
	case StatusOK:
		return "OK"
	case StatusError:
		return "ERROR"
	default:
		return "UNSET"
	}
}

// Span is one traced operation. Spans form a tree via ParentSpanID;
// the root span has an empty ParentSpanID.
//
// A Span is safe for concurrent SetAttr / SetStatus / RecordError
// calls. End must be called exactly once; subsequent calls are
// no-ops. The zero value is not usable — obtain Spans via
// Exporter.StartSpan or StartSpan.
type Span struct {
	// Public fields exposed for marshalling. They are read-only
	// from outside this package after End(); the mutex below
	// guards them while the span is in flight.
	TraceID       string
	SpanID        string
	ParentSpanID  string
	Name          string
	StartTime     time.Time
	EndTime       time.Time
	Attributes    map[string]any
	Status        Status
	StatusMessage string

	// ended is set by End and prevents the post-End Submit path
	// from re-firing. mu guards every mutable field above.
	mu       sync.Mutex
	ended    bool
	exporter *Exporter // non-nil for spans created via a live exporter
}

// StartSpan creates a new span attached to parent. When parent is
// the zero value (no tracing in scope) the new span gets a fresh
// trace id and an empty ParentSpanID — it becomes a root span.
//
// When a process-wide exporter has been registered via
// RegisterExporter, the returned span is bound to that exporter so
// End submits it automatically. When no exporter is registered
// (the default) the span is unbound — End becomes a local
// no-op and the caller is responsible for forwarding the span
// elsewhere if needed.
//
// Most call sites (the chat handler, the per-phase spans inside
// the handler) use Exporter.StartSpan to bind the span directly
// to a *Exporter. The standalone StartSpan is the entry point for
// middleware (auth.Middleware, ratelimit.Middleware,
// SecurityHeaders) which has no per-call access to the exporter
// — the package-level registered exporter carries it.
func StartSpan(parent Context, name string) (Context, *Span) {
	if parent.TraceID == "" {
		parent.TraceID = NewTraceID()
	}
	sid := NewSpanID()
	s := &Span{
		TraceID:      parent.TraceID,
		SpanID:       sid,
		ParentSpanID: parent.SpanID, // empty when parent.SpanID == ""
		Name:         name,
		StartTime:    time.Now(),
		Attributes:   make(map[string]any, 4),
		Status:       StatusUnset,
	}
	if e := globalExporter.Load(); e != nil && e.sampler.ShouldSample(parent.TraceID) {
		s.exporter = e
	}
	return parent.WithSpanID(sid), s
}

// globalExporter is the process-wide exporter registered by
// RegisterExporter. Atomic pointer so concurrent readers (every
// hot-path StartSpan call) pay a single atomic load. Tests that
// want their own exporter call RegisterExporter to swap it.
var globalExporter atomic.Pointer[Exporter]

// RegisterExporter installs e as the process-wide exporter so the
// package-level StartSpan binds new spans to it. Passing nil
// disables the global binding (the next StartSpan returns an
// unbound span). Idempotent — safe to call from multiple
// boot paths; the most recent non-nil pointer wins.
//
// RegisterExporter is the seam the chat handler uses to expose the
// tracing-enabled flag to middleware that has no access to the
// handler's Deps (auth.Middleware, ratelimit.Limiter.Middleware,
// SecurityHeaders). After this call returns Enabled reports
// true and the next StartSpan attaches to e.
func RegisterExporter(e *Exporter) {
	globalExporter.Store(e)
}

// Enabled reports whether a process-wide exporter has been
// registered. Middleware MUST guard span creation with this
// function so the hot path incurs zero allocation when the
// operator leaves NEXUS_TRACING_ENDPOINT empty (issue #71 AC:
// "ZERO overhead when tracing disabled").
//
// The read is a single atomic load; non-tracing builds can
// inline it as a constant. Always paired with the same call that
// runs StartSpan so the two reads see the same value.
func Enabled() bool {
	return globalExporter.Load() != nil
}

// GlobalExporter returns the process-wide exporter registered by
// RegisterExporter, or nil when no exporter is active. The returned
// pointer is safe to read concurrently — it is a snapshot of the
// atomic pointer at the moment of the call. Used by the /metrics
// handler to surface the exporter's dropped-span counter.
func GlobalExporter() *Exporter {
	return globalExporter.Load()
}

// ctxKey is the unexported type used as the context.Context key
// for storing the parent tracing Context. Unexported so external
// packages cannot collide on the same key.
type ctxKey struct{}

// WithSpanContext returns a derived context carrying tc as the
// active parent tracing context. Downstream handlers retrieve it
// via SpanContextFromContext to create child spans attached to
// the same trace id. Returns parent unmodified when tc is the
// zero value — the caller may still stamp it harmlessly.
func WithSpanContext(parent context.Context, tc Context) context.Context {
	if tc.TraceID == "" {
		return parent
	}
	return context.WithValue(parent, ctxKey{}, tc)
}

// SpanContextFromContext returns the tracing Context previously
// stored via WithSpanContext, or the zero value + false when
// none has been set. Use the ok result to decide whether a child
// span attaches to a real parent or starts a fresh root.
func SpanContextFromContext(ctx context.Context) (Context, bool) {
	if ctx == nil {
		return Context{}, false
	}
	v, ok := ctx.Value(ctxKey{}).(Context)
	return v, ok
}

// StartSpanFromContext creates a child span attached to the
// tracing Context stored in ctx by an upstream middleware
// (RequestMiddleware or one of the per-phase middlewares). When
// no parent has been stored, StartSpanFromContext creates a
// fresh root span with the same semantics as StartSpan.
//
// Returns (ctx', span) where ctx' carries the new span id and
// should be propagated to downstream code via r.WithContext.
//
// A nil span is returned when Enabled() is false so callers can
// `defer span.End()` safely (Span methods are nil-safe).
func StartSpanFromContext(ctx context.Context, name string) (context.Context, *Span) {
	if !Enabled() {
		return ctx, nil
	}
	parent, _ := SpanContextFromContext(ctx)
	childCtx, span := StartSpan(parent, name)
	return WithSpanContext(ctx, childCtx), span
}

// SetAttr stores key=val on the span. Safe from any goroutine;
// nil-receiver safe so callers can defer End() without a nil-check.
func (s *Span) SetAttr(key string, val any) {
	if s == nil {
		return
	}
	s.mu.Lock()
	s.Attributes[key] = val
	s.mu.Unlock()
}

// SetStatus stamps the span's status. Passing StatusUnset clears any
// prior status without setting one. Nil-receiver safe.
func (s *Span) SetStatus(code Status, msg string) {
	if s == nil {
		return
	}
	s.mu.Lock()
	s.Status = code
	s.StatusMessage = msg
	s.mu.Unlock()
}

// RecordError stamps the span status to ERROR with the error's text.
// A nil error is ignored so callers can defer RecordError without a
// guard. Nil-receiver safe.
func (s *Span) RecordError(err error) {
	if s == nil || err == nil {
		return
	}
	s.mu.Lock()
	s.Status = StatusError
	s.StatusMessage = err.Error()
	s.mu.Unlock()
}

// End marks the span complete and, when the span was created via an
// Exporter, submits it to the background OTLP/JSON POST loop. After
// End the span's public fields are stable and may be read
// concurrently; calling End twice is a no-op (the second call is
// silently dropped so a misplaced defer is harmless).
//
// If the span was never explicitly statused, End promotes the
// status from UNSET to OK so the OTLP record reflects success.
func (s *Span) End() {
	if s == nil {
		return
	}
	s.mu.Lock()
	if s.ended {
		s.mu.Unlock()
		return
	}
	s.ended = true
	s.EndTime = time.Now()
	if s.Status == StatusUnset {
		s.Status = StatusOK
	}
	exp := s.exporter
	s.mu.Unlock()
	if exp != nil {
		exp.Submit(s)
	}
}

// Command nexus is the entry point for the Nexus Proxy. It loads
// configuration from the environment, constructs the chat handler with its
// collaborators (RAG store, SLM client, formatting regex, judge observer,
// telemetry recorder), and serves /v1/chat/completions.
package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"runtime"
	"sync"
	"syscall"
	"time"

	"github.com/anchapin/nexus-proxy/internal/auth"
	"github.com/anchapin/nexus-proxy/internal/budget"
	"github.com/anchapin/nexus-proxy/internal/circuit"
	"github.com/anchapin/nexus-proxy/internal/concurrencylimit"
	"github.com/anchapin/nexus-proxy/internal/config"
	"github.com/anchapin/nexus-proxy/internal/handlers"
	"github.com/anchapin/nexus-proxy/internal/health"
	"github.com/anchapin/nexus-proxy/internal/judge"
	"github.com/anchapin/nexus-proxy/internal/metrics"
	"github.com/anchapin/nexus-proxy/internal/middleware"
	"github.com/anchapin/nexus-proxy/internal/observability"
	"github.com/anchapin/nexus-proxy/internal/probe"
	"github.com/anchapin/nexus-proxy/internal/providers"
	"github.com/anchapin/nexus-proxy/internal/quality"
	"github.com/anchapin/nexus-proxy/internal/rag"
	"github.com/anchapin/nexus-proxy/internal/ratelimit"
	"github.com/anchapin/nexus-proxy/internal/router"
	"github.com/anchapin/nexus-proxy/internal/telemetry"
	"github.com/anchapin/nexus-proxy/internal/tracing"
	"github.com/anchapin/nexus-proxy/internal/transport"
	"github.com/anchapin/nexus-proxy/internal/upstream"
)

const (
	bootRAGTimeout = 30 * time.Second
)

// version is the build version. Overridden at compile time via
// -ldflags "-X main.version=v1.2.3" in the Makefile and the release
// workflow. The default "dev" lets `nexus --version` work from a
// local `make build` without any special setup.
var version = "dev"

// commit is the git commit SHA. Overridden at compile time via
// -ldflags "-X main.commit=$(git rev-parse HEAD)". Default "unknown".
var commit = "unknown"

// circuitBreakerAdapter bridges the chat handler's CircuitBreakerObserver
// calls into the observability Collector (issue #304).
type circuitBreakerAdapter struct {
	recordFailure      func(string)
	recordRecovery     func(string)
	incEmbedderFailure func(string)
}

func (a circuitBreakerAdapter) RecordCircuitFailure(circuit string)  { a.recordFailure(circuit) }
func (a circuitBreakerAdapter) RecordCircuitRecovery(circuit string) { a.recordRecovery(circuit) }
func (a circuitBreakerAdapter) IncEmbedderFailure(kind string)       { a.incEmbedderFailure(kind) }

func main() {
	startTime := time.Now()

	// Subcommand dispatch (issue #32). The default invocation
	// (no args) starts the proxy; `nexus check` (alias `nexus
	// doctor`) runs the boot-time diagnostic suite and exits.
	// Anything else is reserved for future subcommands; an
	// unknown verb is rejected here so the operator gets a
	// clear error before config.Load runs.
	if len(os.Args) > 1 {
		switch os.Args[1] {
		case "check", "doctor":
			os.Exit(runCheck(os.Args[2:], os.Stdout, os.Stderr))
		case "dashboard":
			os.Exit(runDashboard(os.Args[2:], os.Stdout, os.Stderr))
		case "config":
			os.Exit(runConfig(os.Args[2:], os.Stdout, os.Stderr))
		case "judge":
			os.Exit(runJudgeStats(os.Args[2:], os.Stdout, os.Stderr))
		case "routing-preview":
			os.Exit(runRoutingPreview(os.Args[2:], os.Stdout, os.Stderr))
		case "-h", "--help", "help":
			fmt.Fprintln(os.Stderr, "Usage: nexus [check|doctor|config|dashboard|judge|routing-preview]")
			fmt.Fprintln(os.Stderr, "")
			fmt.Fprintln(os.Stderr, "Run with no arguments to start the proxy.")
			fmt.Fprintln(os.Stderr, "Run `nexus check` to validate boot-time configuration.")
			fmt.Fprintln(os.Stderr, "Run `nexus dashboard` to view the daily savings summary.")
			fmt.Fprintln(os.Stderr, "Run `nexus config validate <file>` to validate a config file.")
			fmt.Fprintln(os.Stderr, "Run `nexus judge stats` to view adaptive routing confidence.")
			fmt.Fprintln(os.Stderr, "Run `nexus routing-preview \"prompt\"` to preview routing decisions.")
			fmt.Fprintln(os.Stderr, "Run `nexus --version` to print the build version.")
			os.Exit(0)
		case "-v", "--version", "version":
			printVersion(os.Stdout)
			os.Exit(0)
		default:
			fmt.Fprintf(os.Stderr, "nexus: unknown subcommand %q\n\n", os.Args[1])
			fmt.Fprintln(os.Stderr, "Usage: nexus [check|doctor|config|dashboard|judge|routing-preview]")
			os.Exit(2)
		}
	}

	cfg, err := config.Load()
	if err != nil {
		// The structured logger is not yet wired, so use the std
		// log.Fatalf path. This is one of two unrecoverable boot
		// errors (issue #3) — every other log call below flows
		// through slog.
		log.Fatalf("config: %v", err)
	}
	logger := cfg.NewLogger()
	slog.SetDefault(logger)

	// Shared pooled HTTP client for all outbound upstream calls (issue #184).
	// Connection pooling reduces TCP handshake overhead across Ollama,
	// frontier API, and arbiter calls. Created once and passed to every
	// collaborator so all traffic shares the same transport.
	httpClient := transport.NewFromEnv()

	emb, err := rag.NewEmbedder(cfg.EmbedderType, cfg.EmbedderBaseURL, cfg.EmbeddingModel, cfg.FrontierKey, httpClient,
		rag.BreakerConfig{Threshold: cfg.RAGCircuitBreakerThreshold, Cooldown: cfg.RAGCircuitBreakerCooldown})
	if err != nil {
		log.Fatalf("rag embedder: %v", err)
	}
	slog.Info("rag embedder configured",
		slog.String("type", string(cfg.EmbedderType)),
		slog.String("model", cfg.EmbeddingModel),
	)
	bootCtx, cancel := context.WithTimeout(context.Background(), bootRAGTimeout)
	defer cancel()

	// RAG embedding cache (issue #115, #303). Wrap the Ollama embedder
	// with a bounded LRU + TTL cache so repeat prompts skip the
	// /api/embeddings round-trip. A size of 0 or TTL of 0 disables
	// the cache (falls back to the raw embedder).
	var ragEmbedder rag.Embedder = emb
	if cfg.RAGEmbedCacheSize > 0 && cfg.RAGEmbedCacheTTL > 0 {
		ragEmbedder = rag.NewEmbedCache(emb, cfg.RAGEmbedCacheSize, cfg.RAGEmbedCacheTTL)
		slog.Info("rag embedding cache enabled",
			slog.Int("max_entries", cfg.RAGEmbedCacheSize),
			slog.Duration("ttl", cfg.RAGEmbedCacheTTL),
		)
	}

	// RAG store (issue #46). When NEXUS_RAG_DB is set, open the
	// SQLite-backed PersistentStore and LoadOrIndex it. The boot
	// path is a one-shot: Load if the DB has rows, otherwise
	// IndexDir (which embeds via Ollama AND persists each result).
	// When NEXUS_RAG_DB is empty we fall back to the legacy
	// in-memory-only Store with the original IndexDir semantics —
	// the proxy is byte-for-byte identical to the pre-issue-46
	// behaviour.
	store, persistentStore, ragWatcher := buildRAGStore(cfg, ragEmbedder, bootCtx)

	slm := router.NewSLMClient(cfg.OllamaURL, cfg.RouterModel, cfg.SLMTimeout, httpClient)
	// Judge-guided adaptive routing (issue #47): the confidence
	// floor/ceiling bound the neutral band the SLM uses when a
	// confidence signal is supplied. Zero values fall back to the
	// router defaults, so this is safe even when the feature is off.
	slm.ConfidenceFloor = cfg.RoutingConfidenceFloor
	slm.ConfidenceCeiling = cfg.RoutingConfidenceCeiling
	// SLMClient no longer has its own internal decision cache (issue #489).
	// The planner-level SLMCache wired below is the sole caching layer and
	// honours NEXUS_SLM_CACHE_TTL=0 as a true kill-switch.

	// Ollama health poller (issue #8). When NEXUS_HEALTH_POLL_INTERVAL
	// is zero the handler treats Ollama as always healthy (useful for
	// containers that know Ollama is co-located and unreachable
	// states are impossible). Otherwise a background goroutine
	// pings /api/tags on the cadence and the chat handler reroutes
	// route=local/route=fusion to frontier when Ollama trips the
	// breaker. The poller's context is the boot context so a
	// fatal-level config error cancels it cleanly.
	var hpoller *health.Health
	if cfg.HealthPollInterval > 0 {
		hpoller = health.New(
			cfg.OllamaURL,
			cfg.LocalModel,
			cfg.HealthPollInterval,
			cfg.HealthBreakerThreshold,
			cfg.HealthProbeTimeout,
			httpClient,
		)
		go hpoller.Run(context.Background())
		defer func() {
			if err := hpoller.Close(); err != nil {
				slog.Warn("health poller close", slog.Any("err", err))
			}
		}()
	} else {
		slog.Info("ollama health poller disabled (NEXUS_HEALTH_POLL_INTERVAL=0)")
	}

	// Hardware-aware VRAM probe (issue #6). Replaces the static
	// NEXUS_TOKEN_GUARDRAIL with a live measurement of the loaded
	// Ollama model's context_length (via /api/ps) and the AMD GPU
	// sysfs VRAM nodes. The manager performs an initial blocking
	// probe so the first proxied request after boot already sees the
	// dynamic budget, then re-polls on the configured cadence. When
	// the probe is disabled (NEXUS_PROBE_INTERVAL=0) the manager
	// still runs the boot probe once and the chat handler falls
	// back to the static value when it produces no budget.
	probeImpl := probe.NewOllamaProbe(cfg.OllamaURL, httpClient)
	probeImpl.BytesPerToken = cfg.ProbeBytesPerToken
	// Thermal throttle threshold (issue #597): when the GPU junction
	// temperature exceeds this value the probe collapses the budget so
	// the router falls back to the static guardrail instead of routing
	// heavy prompts to a thermally-clamped GPU. A zero config value
	// disables the check inside the probe.
	probeImpl.ThermalThreshold = cfg.ProbeThermalThreshold
	// Restrict the VRAM probe's context signal to the configured chat
	// model so a resident embedding model (e.g. nomic-embed-text, 8192
	// context) cannot shrink the chat-route guardrail below the chat
	// model's real window (issue #490). When LocalModel is empty the
	// probe keeps the legacy smallest-across-all behaviour.
	probeImpl.ChatModel = cfg.LocalModel
	if cfg.LocalModel != "" {
		slog.Info("vram probe scoped to chat model",
			slog.String("chat_model", cfg.LocalModel),
		)
	}
	probeMgr := probe.NewManager(probeImpl, cfg.ProbePollInterval, cfg.ProbeTimeout)
	go probeMgr.Run(context.Background())
	defer func() {
		if err := probeMgr.Close(); err != nil {
			slog.Warn("probe manager close", slog.Any("err", err))
		}
	}()
	if cfg.ProbePollInterval > 0 {
		slog.Info("vram probe enabled",
			slog.Duration("interval", cfg.ProbePollInterval),
			slog.Duration("timeout", cfg.ProbeTimeout),
		)
	} else {
		slog.Info("vram probe polling disabled (NEXUS_PROBE_INTERVAL=0); boot snapshot only")
	}

	// VRAM-aware local-route concurrency ceiling (issue #81). The
	// limiter is dormant unless the operator set
	// NEXUS_LOCAL_MAX_CONCURRENT above zero, so a stock deployment is
	// byte-for-byte identical to the pre-#81 unlimited path. When
	// enabled, the effective slot count is recomputed from the latest
	// probe snapshot on every Acquire: min(ceiling, freeVRAM/
	// bytesPerSlot). When the probe is unavailable (still booting,
	// disabled, or every signal missing) the full ceiling is used so a
	// missing probe never opens the floodgates. The closure reads
	// probeMgr directly so the limiter never imports internal/probe.
	var localLimiter handlers.LocalLimiter
	var localConcLimiter *concurrencylimit.Limiter
	if cfg.LocalMaxConcurrent > 0 {
		localConcLimiter = concurrencylimit.New(
			cfg.LocalMaxConcurrent,
			cfg.LocalVRAMBytesPerSlot,
			func() int64 { return probeMgr.Get().FreeVRAMBytes },
		)
		localLimiter = localConcLimiter
		slog.Info("local-route concurrency limiter enabled",
			slog.Int("ceiling", cfg.LocalMaxConcurrent),
			slog.Int64("bytes_per_slot", cfg.LocalVRAMBytesPerSlot),
		)
	} else {
		slog.Info("local-route concurrency limiter disabled (NEXUS_LOCAL_MAX_CONCURRENT<=0)")
	}

	// Local-route cooldown (issue #80). Arms a short cooldown after
	// the cascade detects a local failure so subsequent requests skip
	// local and go directly to the fallback route — closing the gap
	// between the cascade observing failure and the health poller
	// tripping its breaker. Disabled (nil) when NEXUS_LOCAL_COOLDOWN
	// is zero; the hot path is byte-for-byte identical to pre-#80.
	var localCooldown *circuit.Cooldown
	if cfg.LocalCooldown > 0 {
		localCooldown = circuit.New(cfg.LocalCooldown)
		slog.Info("local-route cooldown enabled",
			slog.Duration("cooldown", cfg.LocalCooldown),
		)
	} else {
		slog.Info("local-route cooldown disabled (NEXUS_LOCAL_COOLDOWN<=0)")
	}

	// Trusted-proxy-aware client-IP resolver + per-client rate limiter
	// (issue #75). The resolver honours X-Forwarded-For / X-Real-IP
	// ONLY when the direct TCP peer is in the NEXUS_TRUSTED_PROXIES
	// CIDR allowlist; with an empty list (the default) it trusts
	// nobody and uses the direct peer IP, so an attacker who reaches
	// the proxy directly cannot spoof per-client rate-limit buckets.
	ipResolver := ratelimit.NewClientIPResolver(cfg.TrustedProxies)

	// Boot hardening warning (issue #75). Rate limiting behind a
	// non-loopback bind with no trusted proxies is almost certainly a
	// misconfiguration: either the proxy is directly exposed (so a
	// single NATed IP can exhaust the whole per-client budget by
	// rotating X-Forwarded-For — except the trust-nobody resolver
	// already prevents that), OR the operator meant to put the proxy
	// behind nginx / a cloud LB and forgot to whitelist its CIDR
	// (so legitimate clients all share the proxy's IP bucket). Warn
	// loudly either way; boot never fails on this.
	if cfg.RateLimitEnabled() && !cfg.IsLoopbackBind() && !cfg.TrustedProxiesConfigured() {
		slog.Warn("rate limit enabled on a non-loopback bind with NEXUS_TRUSTED_PROXIES unset: "+
			"all clients behind a NAT/share-IP will share a single bucket. "+
			"Set NEXUS_TRUSTED_PROXIES to the reverse-proxy CIDR, or bind to 127.0.0.1",
			slog.String("addr", cfg.Addr),
			slog.Int("rate_limit_rpm", cfg.RateLimitRPM),
		)
	}

	var rateLimiter *ratelimit.Middleware
	if cfg.RateLimitEnabled() {
		var keyFn func(*http.Request) string
		if cfg.RateLimitByAPIKey {
			keyFn = func(r *http.Request) string {
				ip := ipResolver.Resolve(r)
				return ratelimit.APIKeyAwareKeyFunc(ip, r)
			}
		}
		rateLimiter = ratelimit.NewMiddleware(cfg.RateLimitRPM, cfg.RateLimitBurst, ipResolver, keyFn)
		slog.Info("rate limiter enabled",
			slog.Int("rpm", cfg.RateLimitRPM),
			slog.Int("burst", cfg.RateLimitBurst),
			slog.Bool("trusted_proxies", cfg.TrustedProxiesConfigured()),
			slog.Bool("by_api_key", cfg.RateLimitByAPIKey),
		)
	} else {
		slog.Info("rate limiter disabled (NEXUS_RATE_LIMIT_RPM<=0)")
	}

	// Graceful shutdown sanity check (issue #121). The drain window
	// must be at least as long as the inbound read deadline —
	// otherwise a SIGTERM that arrives while a client is still
	// uploading a large request body truncates that request mid-read
	// even though the server nominally had time to finish it. Warn
	// (rather than fail boot) so an operator who deliberately wants a
	// tight drain can keep it; the warning makes the truncation
	// visible in the logs. Skipped when ReadTimeout is 0 (disabled),
	// since there is no inbound deadline to underrun.
	if cfg.ReadTimeout > 0 && cfg.ShutdownTimeout < cfg.ReadTimeout {
		slog.Warn("shutdown drain shorter than read timeout: in-flight uploads may be truncated mid-read",
			slog.Duration("shutdown_timeout", cfg.ShutdownTimeout),
			slog.Duration("read_timeout", cfg.ReadTimeout),
			slog.String("hint", "set NEXUS_SHUTDOWN_TIMEOUT >= NEXUS_SERVER_READ_TIMEOUT"),
		)
	}
	slog.Info("graceful shutdown drain configured",
		slog.Duration("shutdown_timeout", cfg.ShutdownTimeout),
	)

	// Async LLM-as-a-judge evaluator (issue #15). The handler never
	// imports internal/judge; we plug the observer in here via a
	// closure that adapts LocalCompletion to the evaluator's
	// Sample + Enqueue entry points.
	var (
		judgeEval       *judge.Evaluator
		judgeObs        handlers.JudgeObserver
		confidenceStore *router.SQLiteConfidenceStore
		confidenceObs   router.ConfidenceStore
	)

	// Budget guard for tracking spend (issue #183). Created early so it
	// can be passed to the judge evaluator. When BudgetEnabled is false
	// the guard is a no-op (limit=0).
	var budgetGuard *budget.Guard
	if cfg.BudgetEnabled() {
		budgetGuard = budget.NewGuard(cfg.BudgetDailyLimit)
		if cfg.BudgetAlertEnabled {
			alerter := budget.NewPrometheusAlerter(slog.Default())
			budgetGuard.SetAlerter(alerter)
			slog.Info("budget alerting enabled",
				slog.Float64("limit_usd", cfg.BudgetDailyLimit),
			)
		}
	}

	// Route-decision counters (issue #74, #226). Declared early so the
	// judge and quality observers can reference it; mux.Handle and the
	// Handler() call stay in the late-setup block below.
	routeCounters := observability.NewRouteCounters()

	// Wire the local-route cooldown failure observer into the route
	// counters after both are initialised (issue #530).
	if localCooldown != nil {
		localCooldown.SetFailureObserver(func() {
			routeCounters.IncLocalCooldownTriggers()
		})
	}

	// Circuit breaker metrics collector (issue #304). Created early so it
	// is available for wiring into the chat handler Deps.
	circuitCollector := observability.NewCollector()

	// Stage latency collector (issue #300). Separate from routeCounters
	// so the per-stage histograms (RAGRetrievalMs, PromptEngineeringMs,
	// TOONCompressionMs, SLMRoutingMs, UpstreamFirstByteMs) are collected
	// without disturbing the existing /metrics route-counter path.
	stageCollector := observability.NewCollector()
	if cfg.JudgeEnabled && cfg.JudgeAPIKey != "" {
		evalCfg := judge.Config{
			URL:         cfg.JudgeURL,
			Model:       cfg.JudgeModel,
			APIKey:      cfg.JudgeAPIKey,
			SampleRate:  cfg.JudgeSampleRate,
			Concurrency: cfg.JudgeConcurrency,
			QueueDepth:  cfg.JudgeQueueDepth,
			Timeout:     cfg.JudgeTimeout,
			CostPer1K:   cfg.JudgeCostPer1KUSD,
			BudgetGuard: budgetGuard,
		}
		// Issue #198: open the SQLite-backed judge store when
		// NEXUS_JUDGE_DB is set (default path if unset). On error
		// we log and fall back to the in-memory MemoryStorage so
		// the proxy stays alive — judge scores are best-effort
		// telemetry, not a correctness requirement.
		var storage judge.Storage
		if cfg.JudgeDBEnabled() {
			store, err := judge.OpenSQLiteStore(cfg.JudgeDBPath)
			if err != nil {
				slog.Error("judge SQLite store open failed, falling back to in-memory",
					slog.String("path", cfg.JudgeDBPath),
					slog.Any("err", err),
				)
				storage = judge.NewMemoryStorage()
			} else {
				storage = store
				slog.Info("judge SQLite store opened",
					slog.String("path", store.Path()),
				)
			}
		} else {
			storage = judge.NewMemoryStorage()
			slog.Info("judge SQLite store disabled (NEXUS_JUDGE_DB is empty); using in-memory store")
		}

		// Judge-guided adaptive routing (issue #47). When enabled we
		// open the confidence store and wrap the judge storage in a
		// bridge that feeds each landed JudgeScore back into the store
		// as a per-category local outcome. The observer stashes the
		// prompt category at enqueue time so the bridge can resolve it
		// when the async score arrives.
		var bridge *confidenceBridge
		if cfg.RoutingConfidenceEnabled() {
			cs, cerr := router.OpenConfidenceStore(router.ConfidenceConfig{
				Path:       cfg.RoutingConfidenceDB,
				MinSamples: cfg.RoutingConfidenceMinSamples,
				Window:     cfg.RoutingConfidenceWindow,
			})
			if cerr != nil {
				slog.Error("routing confidence store open failed, adaptive routing disabled",
					slog.Any("err", cerr))
			} else {
				confidenceStore = cs
				confidenceObs = cs
				bridge = newConfidenceBridge(storage, cs)
				storage = bridge
				slog.Info("adaptive routing enabled",
					slog.String("db", cs.Path()),
					slog.Float64("floor", cfg.RoutingConfidenceFloor),
					slog.Float64("ceiling", cfg.RoutingConfidenceCeiling),
					slog.Int("min_samples", cfg.RoutingConfidenceMinSamples),
					slog.Duration("window", cfg.RoutingConfidenceWindow),
				)
			}
		}

		judgeEval = judge.NewEvaluator(evalCfg, httpClient, storage)
		judgeObs = handlers.JudgeObserverFunc(func(c handlers.LocalCompletion) bool {
			if !judgeEval.Sample() {
				return false
			}
			if bridge != nil {
				bridge.note(c.RequestID, router.Categorize(c.Instruction))
			}
			if !judgeEval.Enqueue(judge.Sample{
				RequestID:   c.RequestID,
				Instruction: c.Instruction,
				Output:      c.Output,
				LocalModel:  c.LocalModel,
				TraceParent: c.TraceParent,
				TraceState:  c.TraceState,
			}) {
				if bridge != nil {
					bridge.forget(c.RequestID)
				}
				routeCounters.ObserveJudgeQueueOverflow()
				slog.Warn("judge queue full, dropped request", slog.String("request_id", c.RequestID))
				return false
			}
			return true
		})
		slog.Info("judge enabled",
			slog.String("url", cfg.JudgeURL),
			slog.String("model", cfg.JudgeModel),
			slog.Float64("sample_rate", cfg.JudgeSampleRate),
			slog.Int("concurrency", cfg.JudgeConcurrency),
		)
	} else {
		slog.Info("judge disabled (sample rate <= 0 or no api key)")
	}
	// The confidence store's lifetime is tied to the judge storage
	// (the bridge delegates Close to the inner judge storage), but the
	// underlying *sql.DB is owned here. Closing it on shutdown flushes
	// WAL frames. judgeEval.Close (below, on signal) drains the queue
	// first, so any in-flight outcome is recorded before this runs.
	defer func() {
		if confidenceStore != nil {
			if err := confidenceStore.Close(); err != nil {
				slog.Warn("routing confidence store close", slog.Any("err", err))
			}
		}
	}()

	recorder := buildRecorder(cfg)
	defer func() {
		if err := recorder.Close(); err != nil {
			slog.Error("telemetry close", slog.Any("err", err))
		}
	}()

	// Frontier provider registry (issue #223). When NEXUS_FRONTIER_PROVIDERS
	// is set, ParseProvidersFromEnv parses the JSON array and returns a
	// registry of Provider objects. When nil the chat handler falls back
	// to the legacy config-based cascade (BuildLocalCascade) so existing
	// deployments are byte-for-byte unchanged.
	providerRegistry, err := providers.ParseProvidersFromEnv()
	if err != nil {
		log.Fatalf("providers: %v", err)
	}
	if providerRegistry != nil {
		slog.Info("frontier provider registry loaded",
			slog.Int("providers", providerRegistry.Len()),
			slog.String("names", fmt.Sprintf("%v", providerRegistry.ProviderNames())),
		)
	}

	// File watcher (issue #46). Spawned only when persistence is
	// enabled AND the operator set NEXUS_RAG_POLL_INTERVAL > 0.
	// Stop blocks on shutdown so the goroutine has a chance to
	// drain before the DB handle closes below.
	if ragWatcher != nil {
		defer func() {
			ragWatcher.Stop()
			slog.Info("rag watcher stopped")
		}()
	}

	// Persistent store (issue #46). Close flushes WAL frames after
	// the watcher has stopped, so any final Upsert from a pending
	// scan lands on disk.
	if persistentStore != nil {
		defer func() {
			if err := persistentStore.Close(); err != nil {
				slog.Warn("rag persistent store close", slog.Any("err", err))
			}
		}()
	}

	// SQLite-backed metrics store (issue #4). When configured the
	// per-request savings events go here; the JSONL recorder above
	// is left in place so operators can still get a tail-friendly
	// log. Hand-off via MetricsObserver keeps the handlers package
	// free of the metrics import (same dependency rule as judge
	// and quality).
	metricsStore, metricsObs := buildMetrics(cfg)
	defer func() {
		if metricsStore != nil {
			if err := metricsStore.Close(); err != nil {
				slog.Error("metrics close", slog.Any("err", err))
			}
		}
	}()

	// Async AST/compiler verifier (issue #13). The handler never
	// imports internal/quality; we plug a closure in that maps the
	// handler's QualityEvent shape to the verifier's Event shape
	// and dispatches via the verifier's non-blocking Submit. The
	// verifier is dormant when QualityConcurrency is non-positive
	// — same pattern as the judge, so the handler is unaffected
	// when the operator leaves the verifier disabled.
	var (
		verifier *quality.ShellVerifier
		qualityO handlers.QualityObserver
	)
	if cfg.QualityEnabled {
		verifier = quality.NewShellVerifier(quality.Config{
			Concurrency: cfg.QualityConcurrency,
			QueueDepth:  cfg.QualityQueueDepth,
			Timeout:     cfg.QualityTimeout,
			StderrCap:   cfg.QualityStderrCap,
			Observer: quality.ObserverFunc(func(v quality.Verdict) {
				// Sink: forward to the telemetry row keyed by
				// request id (issue #16 will materialise this
				// in the SQLite schema). For now we log the
				// verdict so operators can confirm the worker
				// is doing real work.
				if v.Err != nil {
					slog.Warn("quality verdict error",
						slog.String("request_id", v.Event.RequestID),
						slog.String("path", v.Event.Path),
						slog.String("repo_root", v.RepoRoot),
						slog.Bool("pass", v.Pass),
						slog.Int("exit_code", v.ExitCode),
						slog.Any("err", v.Err),
					)
					return
				}
				slog.Info("quality verdict",
					slog.String("request_id", v.Event.RequestID),
					slog.String("path", v.Event.Path),
					slog.String("repo_root", v.RepoRoot),
					slog.String("kind", string(v.Kind)),
					slog.Bool("pass", v.Pass),
					slog.Int("exit_code", v.ExitCode),
					slog.Int64("duration_ms", v.DurationMs),
				)
			}),
		})
		qualityO = handlers.QualityObserverFunc(func(e handlers.QualityEvent) {
			if !verifier.Submit(quality.Event{
				RequestID:   e.RequestID,
				Path:        e.Path,
				ToolName:    e.ToolName,
				TraceParent: e.TraceParent,
				TraceState:  e.TraceState,
			}) {
				routeCounters.ObserveQualityQueueOverflow()
				slog.Warn("quality queue full, dropped request",
					slog.String("request_id", e.RequestID),
					slog.String("path", e.Path),
				)
			}
		})
		slog.Info("quality verifier enabled",
			slog.Int("concurrency", cfg.QualityConcurrency),
			slog.Int("queue", cfg.QualityQueueDepth),
			slog.Duration("timeout", cfg.QualityTimeout),
		)
	} else {
		slog.Info("quality verifier disabled (concurrency <= 0)")
	}
	defer func() {
		if verifier != nil {
			if err := verifier.Close(); err != nil {
				slog.Warn("quality verifier close", slog.Any("err", err))
			}
		}
	}()

	// Wire dropped-counter gauge providers into /metrics (issue #442).
	// Each provider reads the cumulative drop count from its backing
	// store at scrape time so the Prometheus counter stays live.
	routeCounters.SetGaugeProviders(
		observability.GaugeProviderFunc(func() []observability.GaugeSample {
			var v uint64
			if verifier != nil {
				v = verifier.Dropped()
			}
			return []observability.GaugeSample{{
				Name:  "nexus_quality_dropped_total",
				Value: float64(v),
			}}
		}),
		observability.GaugeProviderFunc(func() []observability.GaugeSample {
			var v uint64
			if ms, ok := metricsStore.(*metrics.SQLiteStore); ok {
				v = ms.Dropped()
			}
			return []observability.GaugeSample{{
				Name:  "nexus_metrics_dropped_total",
				Value: float64(v),
			}}
		}),
		observability.GaugeProviderFunc(func() []observability.GaugeSample {
			ms, ok := metricsStore.(*metrics.SQLiteStore)
			if !ok || cfg.MetricsRetentionDays <= 0 {
				return nil
			}
			return []observability.GaugeSample{
				{Name: "nexus_metrics_prune_last_rows", Value: float64(ms.PruneLastRows())},
				{Name: "nexus_metrics_prune_last_timestamp_seconds", Value: float64(ms.PruneLastTimestamp())},
			}
		}),
		observability.GaugeProviderFunc(func() []observability.GaugeSample {
			var v uint64
			if d, ok := recorder.(interface{ Dropped() uint64 }); ok {
				v = d.Dropped()
			}
			return []observability.GaugeSample{{
				Name:  "nexus_telemetry_dropped_total",
				Value: float64(v),
			}}
		}),
		observability.GaugeProviderFunc(func() []observability.GaugeSample {
			var v uint64
			if r, ok := recorder.(interface{ Rotations() uint64 }); ok {
				v = r.Rotations()
			}
			return []observability.GaugeSample{{
				Name:  "nexus_telemetry_rotations_total",
				Value: float64(v),
			}}
		}),
		observability.GaugeProviderFunc(func() []observability.GaugeSample {
			return []observability.GaugeSample{{
				Name:  "nexus_tracing_dropped_total",
				Value: float64(tracing.GlobalExporter().Dropped()),
			}}
		}),
		observability.GaugeProviderFunc(func() []observability.GaugeSample {
			return []observability.GaugeSample{{
				Name:  "nexus_tracing_flush_failures_total",
				Value: float64(tracing.GlobalExporter().FlushFailures()),
			}}
		}),
		// Tracing queue-depth gauge (issue #596). Exposes the live
		// number of spans buffered in the export queue so operators
		// can alert on exporter saturation before spans are dropped.
		observability.GaugeProviderFunc(func() []observability.GaugeSample {
			return []observability.GaugeSample{{
				Name:  "nexus_tracing_queue_depth",
				Value: float64(tracing.GlobalExporter().QueueDepth()),
			}}
		}),
		observability.GaugeProviderFunc(func() []observability.GaugeSample {
			if localConcLimiter == nil {
				return nil
			}
			return []observability.GaugeSample{
				{Name: "nexus_local_concurrency_effective_slots", Value: float64(localConcLimiter.Effective())},
				{Name: "nexus_local_concurrency_in_flight", Value: float64(localConcLimiter.InFlight())},
			}
		}),
		// Local-route cooldown gauge (issue #530).
		observability.GaugeProviderFunc(func() []observability.GaugeSample {
			if localCooldown == nil {
				return nil
			}
			var v float64
			if localCooldown.Active() {
				v = 1
			}
			return []observability.GaugeSample{{
				Name:  "nexus_local_cooldown_active",
				Value: v,
			}}
		}),
		// Build info gauge (issue #529). Static metadata — always 1.
		observability.GaugeProviderFunc(func() []observability.GaugeSample {
			return []observability.GaugeSample{{
				Name: "nexus_build_info",
				Labels: map[string]string{
					"version":    version,
					"commit":     commit,
					"go_version": runtime.Version(),
				},
				Value: 1,
			}}
		}),
	)

	// Middleware chain (issue #224). Initialize the middleware registry
	// with the config values so closures capture the per-config state.
	// Empty MiddlewareChain uses the built-in default chain.
	middleware.Init(cfg.MetaPrompt, cfg.TOONNotice, cfg.TOONUnfenced, cfg.PromptInjectionIsolated())
	var mwChain []middleware.Middleware
	if cfg.MiddlewareChain != "" {
		var err error
		mwChain, err = middleware.BuildChain(cfg.MiddlewareChain)
		if err != nil {
			log.Fatalf("middleware chain: %v", err)
		}
		slog.Info("middleware chain configured",
			slog.String("chain", cfg.MiddlewareChain),
			slog.Int("count", len(mwChain)),
		)
	}
	// ContextAwareRAG is the RAG middleware that needs request context.
	// Nil when the chain doesn't contain "rag" (operator removed it).
	var ctxAwareRAG middleware.ContextMiddleware
	if len(mwChain) > 0 || cfg.MiddlewareChain == "" {
		ctxAwareRAG = middleware.NewRAGMiddleware(store)
	}

	mux := http.NewServeMux()

	// Route-decision counters (issue #74). The in-process counter set
	// records every planner Decision that crosses the chat handler so
	// operators get a Prometheus-text view of routing attribution
	// without depending on the JSONL file or the SQLite store. The
	// handler never imports observability — this closure adapts the
	// neutral RouteDecisionEvent shape to the RouteCounters.Observe
	// signature. /metrics is served by the handler returned by
	// RouteCounters.Handler() so a scrape is always an atomic
	// snapshot.
	routeDecisionObs := handlers.RouteDecisionObserverFunc(func(e handlers.RouteDecisionEvent) {
		routeCounters.Observe(e.Route, e.Source, e.Confidence, e.TaskType, "")
		// Issue #206: record SLM cache hit/miss.
		if e.CacheHit {
			routeCounters.ObserveSLMCacheHit(e.CacheHitKind)
		} else {
			routeCounters.ObserveSLMCacheMiss()
		}
	})
	// Rejection observer (issue #119). The chat handler dispatches
	// one RejectionEvent per early-return path; the closure forwards
	// the reason to the in-process counter so it surfaces in
	// /metrics as nexus_requests_rejected_total{reason}. The
	// rate-limit middleware's 429 path is wired separately below
	// because it fires before the chat handler.
	rejectionObs := handlers.RejectionObserverFunc(func(e handlers.RejectionEvent) {
		routeCounters.ObserveRejection(e.Reason)
	})
	// Fusion outcome observer (issue #187). Records whether the fusion
	// arbiter was skipped (panel members agreed) or invoked (disagreement).
	// Surfaces as nexus_fusion_arbiter_total{outcome="skipped"|"invoked"}.
	fusionOutcomeObs := handlers.FusionOutcomeObserverFunc(func(e handlers.FusionOutcomeEvent) {
		routeCounters.ObserveFusionOutcome(e.ArbiterSkipped)
	})
	// Cascade fallback observer (issue #205): the chat handler dispatches
	// one CascadeFallbackEvent per request when a retryable step failure
	// caused the cascade to fall back to the next step. The closure
	// forwards the reason to the in-process counter so it surfaces in
	// /metrics as nexus_cascade_fallback_total{reason}.
	cascadeFallbackObs := handlers.CascadeFallbackObserverFunc(func(e handlers.CascadeFallbackEvent) {
		routeCounters.ObserveCascadeFallback(e.Reason)
	})
	// Arbiter cache observer (issue #232). The chat handler reports
	// cache hits and misses for fusion arbiter synthesis via this
	// closure, which forwards to the in-process counter so it
	// surfaces in /metrics as nexus_fusion_arbiter_cache_total{hit}.
	var arbiterCacheObserver func(bool)
	if cfg.ArbiterCacheTTL > 0 {
		arbiterCacheObserver = func(cacheHit bool) {
			routeCounters.ObserveArbiterCacheHit(cacheHit)
		}
	}
	// Panel panic observer (issue #309). The chat handler detects
	// "panic:" in error messages from Panel/PanelStreaming and
	// calls this observer, which forwards to the in-process counter
	// so it surfaces in /metrics as nexus_panel_panics_total.
	panelPanicObs := func() {
		routeCounters.ObservePanelPanic()
	}
	// Prompt-injection hit observer (issue #482). The chat handler calls
	// this once per request that produced >=1 suspicious-pattern hit,
	// forwarding the injection mode ("warn" or "strict") so the
	// nexus_prompt_injection_hits_total{mode} counter can be alerted on.
	injectionHitObs := func(mode string) {
		routeCounters.ObservePromptInjectionHit(mode)
	}
	// Upstream response body cap (issue #533). Configure once at startup
	// so the configured NEXUS_MAX_RESPONSE_BYTES value is authoritative
	// for BufferedFetchWithContext, FetchPanel, and fetchCascadeStep.
	upstream.ConfigureMaxResponseBytes(int64(cfg.EffectiveMaxResponseBytes()))
	if cfg.EffectiveMaxResponseBytes() < config.DefaultMaxResponseBytes {
		slog.Warn("upstream response body cap is below the 64 MiB default",
			slog.Int("max_response_bytes", cfg.EffectiveMaxResponseBytes()),
			slog.String("hint", "operator is tightening the cap; confirm this is intentional"),
		)
	}
	// Arbiter synthesis cache (issue #232, #773). Created when TTL > 0;
	// nil means caching is disabled.
	var arbiterCache *upstream.ArbiterCache
	if cfg.ArbiterCacheTTL > 0 {
		arbiterCache = upstream.NewArbiterCache(cfg.ArbiterCacheTTL, cfg.ArbiterCacheMaxEntries)
		slog.Info("fusion arbiter cache enabled",
			slog.Duration("ttl", cfg.ArbiterCacheTTL),
			slog.Int("max_entries", cfg.ArbiterCacheMaxEntries),
		)
	}
	mux.Handle("/metrics", routeCounters.Handler())
	slog.Info("metrics endpoint serves prometheus text format",
		slog.String("path", "/metrics"),
	)

	// Stage latency histograms (issue #300): per-stage breakdown of
	// RAGRetrievalMs, PromptEngineeringMs, TOONCompressionMs,
	// SLMRoutingMs, UpstreamFirstByteMs. Exposed as a separate
	// /metrics/stages endpoint so operators can correlate pipeline
	// overhead with overall latency without changing the existing
	// /metrics schema.
	mux.Handle("/metrics/stages", stageCollector.Handler())
	slog.Info("stage latency histograms exposed",
		slog.String("path", "/metrics/stages"),
	)

	ragObserver := handlers.RAGObserverFunc(func(e handlers.RAGEvent) {
		if e.Hit {
			routeCounters.ObserveRAGHit()
		} else {
			routeCounters.ObserveRAGMiss(e.MissReason)
		}
		// RAG similarity histogram (issue #447, #671). Only recorded when
		// Retrieve actually performed a search — empty-store and
		// embed-error events carry no path/score so we skip them to
		// avoid spurious bucket advancement for the "no candidate
		// scored" sentinel. The effective threshold label (e.EffectiveThreshold)
		// enables per-domain tuning visibility.
		if e.IndexPath != "" {
			outcome := "miss"
			if e.Hit {
				outcome = "hit"
			}
			circuitCollector.ObserveRAGSimilarity(e.IndexPath, outcome, e.Score, e.EffectiveThreshold)
		}
	})

	// RAG embedding cache hit/miss observer (issue #303).
	ragCacheObserver := func(hit bool) {
		if hit {
			routeCounters.ObserveRAGCacheHit()
		} else {
			routeCounters.ObserveRAGCacheMiss()
		}
	}

	// SLM decision cache (issue #206). When NEXUS_SLM_CACHE_TTL > 0,
	// deduplicate identical prompts within the TTL window so repeated
	// requests don't trigger an SLM call.
	var slmCache *router.SLMCache
	if cfg.SLMCacheEnabled() {
		if cfg.SLMCacheSemanticThreshold > 0 {
			slmCache = router.NewSLMCacheWithEmbedder(cfg.SLMCacheTTL, cfg.SLMCacheMaxEntries, ragEmbedder, cfg.SLMCacheSemanticThreshold)
			slog.Info("slm decision cache enabled (with semantic deduplication)",
				slog.Duration("ttl", cfg.SLMCacheTTL),
				slog.Int("max_entries", cfg.SLMCacheMaxEntries),
				slog.Float64("semantic_threshold", cfg.SLMCacheSemanticThreshold),
			)
		} else {
			slmCache = router.NewSLMCache(cfg.SLMCacheTTL, cfg.SLMCacheMaxEntries)
			slog.Info("slm decision cache enabled",
				slog.Duration("ttl", cfg.SLMCacheTTL),
				slog.Int("max_entries", cfg.SLMCacheMaxEntries),
			)
		}
		// Issue #449: forward every TTL/LRU eviction into the route
		// counters so /metrics shows nexus_slm_cache_evictions_total
		// with reason="ttl" or "lru". Distinguishing the two paths lets
		// operators tell whether the cache is undersized (high lru) or
		// its TTL is too short (high ttl) without changing the cache
		// configuration.
		slmCache.SetEvictionObserver(func(reason string) {
			routeCounters.ObserveSLMCacheEviction(reason)
		})
		// Wire the embed-error observer so embedder degradation is
		// observable as nexus_slm_cache_embedding_errors_total instead
		// of silently appearing as cache misses (issue #741).
		slmCache.SetEmbedErrorObserver(func() {
			routeCounters.ObserveSLMCacheEmbedError()
		})
	} else {
		slog.Info("slm decision cache disabled (NEXUS_SLMCACHE_TTL<=0)")
	}

	// SLM decision cache gauges (issue #531).
	routeCounters.SetGaugeProviders(
		observability.GaugeProviderFunc(func() []observability.GaugeSample {
			if slmCache == nil {
				return nil
			}
			return []observability.GaugeSample{
				{Name: "nexus_slm_cache_entries", Value: float64(slmCache.Len())},
				{Name: "nexus_slm_cache_max_entries", Value: float64(slmCache.MaxEntries())},
			}
		}),
	)

	// Wire circuit breaker metrics into the /metrics output (issue #304).
	routeCounters.SetCollector(circuitCollector)

	circuitBreakerObs := circuitBreakerAdapter{
		recordFailure:      circuitCollector.RecordCircuitFailure,
		recordRecovery:     circuitCollector.RecordCircuitRecovery,
		incEmbedderFailure: circuitCollector.IncEmbedderFailure,
	}

	chatHandler := handlers.Chat(handlers.Deps{
		Config:                  cfg,
		Client:                  httpClient,
		RAG:                     store,
		SLM:                     slm,
		MiddlewareChain:         mwChain,
		ContextAwareRAG:         ctxAwareRAG,
		Confidence:              confidenceObs,
		SLMCache:                slmCache,
		JudgeObserver:           judgeObs,
		QualityObserver:         qualityO,
		MetricsObserver:         metricsObs,
		Recorder:                recorder,
		Health:                  hpoller,
		BudgetObserver:          budgetObserver(probeMgr),
		SpendGuard:              budgetGuard, // nil when budget disabled (issue #220)
		LocalLimiter:            localLimiter,
		LocalCooldown:           localCooldown,
		RouteDecisionObserver:   routeDecisionObs,
		RejectionObserver:       rejectionObs,
		FusionOutcomeObserver:   fusionOutcomeObs,
		RAGObserver:             ragObserver,
		RAGCacheObserver:        ragCacheObserver,
		CascadeFallbackObserver: cascadeFallbackObs,
		ArbiterCacheObserver:    arbiterCacheObserver,
		PanelPanicObserver:      panelPanicObs,
		InjectionHitObserver:    injectionHitObs,
		CircuitBreakerObserver:  circuitBreakerObs,
		ArbiterCache:            arbiterCache,
		Providers:               providerRegistry,
		PipelineStageObserver: handlers.PipelineStageObserverFunc(
			func(e handlers.PipelineStageEvent) {
				stageCollector.ObservePipelineStage(observability.PipelineStageEvent{
					RAGRetrievalMs:      e.RAGRetrievalMs,
					PromptEngineeringMs: e.PromptEngineeringMs,
					TOONCompressionMs:   e.TOONCompressionMs,
					SLMRoutingMs:        e.SLMRoutingMs,
					UpstreamFirstByteMs: e.UpstreamFirstByteMs,
					SLMConfidence:       e.SLMConfidence,
					SLMTaskType:         e.SLMTaskType,
				})
			},
		),
		LocalPatternsRegex: cfg.DSLLocalPatterns, // issue #298
	})
	// Apply the per-client rate limiter (issue #75) as the outermost
	// wrapper so a flood of requests is rejected before any middleware
	// / RAG / routing work runs. A nil/disabled limiter returns the
	// handler unchanged (zero overhead).
	//
	// Issue #119: install the rejection hook so a 429 increments the
	// nexus_requests_rejected_total{reason="rate_limit"} counter,
	// making rate-limit rejections visible in /metrics alongside the
	// handler-level rejections (method, body_too_large, bad_request).
	if rateLimiter != nil {
		rateLimiter.SetRejectionHook(func() {
			routeCounters.ObserveRejection(handlers.RejectionRateLimit)
		})
		// Issue #746: install the allow hook so bucket utilization is
		// recorded before the token is consumed.
		rateLimiter.SetAllowHook(func(bucketID string, utilizationPct float64) {
			circuitCollector.ObserveRateLimitUtilization(bucketID, utilizationPct)
		})
		chatHandler = rateLimiter.Wrap(chatHandler)
	}
	mux.Handle("/v1/chat/completions", chatHandler)

	// /healthz returns a small JSON document so operators can see
	// the dynamic VRAM budget without scraping logs (issue #6).
	// Status code is always 200 when the binary is alive; the body
	// carries the bootstrap state (`ollama_healthy`,
	// `budget_tokens`, `budget_source`). Compose/K8s liveness probes
	// that pipe `curl /healthz` into grep will still match the
	// `"status":"ok"` field.
	mux.HandleFunc("/healthz", healthzHandler(hpoller, probeMgr, cfg))
	slog.Info("healthz endpoint serves dynamic budget JSON",
		slog.String("ollama_url", cfg.OllamaURL),
	)

	// /readyz is the Kubernetes readiness probe (issue #42). In
	// "degraded" mode (the default) it always returns 200 so a
	// transient Ollama outage never evicts the pod; the body
	// surfaces the degraded flag for dashboards to act on. In
	// "strict" mode it returns 503 when neither Ollama nor a
	// frontier key is available, so the kubelet stops routing
	// traffic to the pod until it recovers.
	mux.HandleFunc("/readyz", handlers.ReadyzHandler(handlers.ReadyzDeps{
		Health:             hpoller,
		FrontierConfigured: cfg.FrontierEnabled(),
		Mode:               cfg.ReadinessMode,
	}))
	slog.Info("readyz endpoint registered",
		slog.String("mode", cfg.ReadinessMode),
	)

	// /status serves a JSON diagnostic snapshot of all async subsystems
	// (issue #225): judge queue depth/capacity, quality queue depth/capacity,
	// RAG embedding health, and a routing distribution snapshot. Primary
	// interface for Kubernetes readiness probes and on-call engineers.
	mux.Handle("/status", handlers.Status(handlers.StatusDeps{
		JudgeEnabled:  func() bool { return judgeEval != nil && judgeEval.Enabled() },
		JudgeDepth:    func() int { return judgeEval.QueueDepth() },
		JudgeCapacity: func() int { return cfg.JudgeQueueDepth },
		JudgeWorkers: func() int {
			if judgeEval == nil {
				return 0
			}
			return judgeEval.Concurrency()
		},
		QualityEnabled: func() bool { return verifier != nil && verifier.Enabled() },
		QualityDepth: func() int {
			if verifier == nil {
				return 0
